package com.team2052.lib.commands;

import org.wpilib.command3.Command;

public interface CommandBase {

  /**
   * Creates and returns the{@link Command} generated by this interface. Does NOT run the {@link
   * Command}, only returns it. Can be used to initialize it for large commands that may require
   * significant runtime to generate.
   *
   * @return the created {@link Command}
   */
  Command create();
}
